import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = sum(1 for a in op if a == 'C')
    opp_d = n - opp_c
    me_d = sum(1 for a in me if a == 'D')

    # Endgame: defect if opponent is exploitable (cooperative), otherwise retaliate if they defect.
    if n >= 97:
        if opp_d <= 3:
            return 'D'
        last = op[-1]
        if last == 'D':
            return 'D'
        # against mild defector, exploit cautiously
        if opp_d * 4 < n:
            return 'D'
        return 'C'

    # Very cooperative opponent: keep cooperating, with light late exploitation only.
    if opp_d == 0:
        if n >= 80 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Very defective opponent: protect, but probe occasionally to escape DD.
    if opp_d >= opp_c + 4 or (n >= 6 and opp_c == 0):
        if op[-1] == 'C' and opp_c >= 2 and rng.random() < 0.6:
            return 'C'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    last_me, last_op = history[-1]

    # Forgiveness after mutual defection loops.
    recent = history[-8:]
    rec_op_d = sum(1 for x in recent if x[1] == 'D')
    rec_me_d = sum(1 for x in recent if x[0] == 'D')
    rec_op_c = sum(1 for x in recent if x[1] == 'C')
    if rec_op_d >= 5 and rec_me_d >= 4:
        if rng.random() < 0.7:
            return 'C'

    # If opponent defected last.
    if last_op == 'D':
        # If we cooperated last and they punished, retaliate strongly.
        if last_me == 'C':
            return 'D'
        # If we defected last and they defected, occasional forgiving reset.
        if rec_op_d >= 3 and rng.random() < 0.4:
            return 'C'
        # If opponent mostly cooperates overall, forgive single defections.
        if opp_d * 5 <= n and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    # If we defected last and they cooperate, we got a free win; but avoid endless exploitation
    # only when opponent looks retaliatory. Against patient cooperators, exploit more.
    if last_me == 'D':
        if opp_d >= 3:
            return 'C'
        if rng.random() < 0.65:
            return 'D'
        return 'C'

    # Occasional probing against highly cooperative but not pure opponents.
    if opp_d * 6 < n and n < 90:
        if rng.random() < 0.04:
            return 'D'

    return 'C'
